INSERT INTO modules (module_id,category,title,description,order_index) VALUES
(3, 'TECHNOLOGY', 'Công nghệ & IT', 'Tiếng Anh giao tiếp thực tế trong công nghệ & it', 3),
(4, 'HEALTHCARE', 'Y tế & chăm sóc sức khỏe', 'Tiếng Anh giao tiếp thực tế trong y tế & chăm sóc sức khỏe', 4),
(5, 'EDUCATION', 'Giáo dục & học tập', 'Tiếng Anh giao tiếp thực tế trong giáo dục & học tập', 5),
(6, 'RECRUITMENT', 'Tuyển dụng & nhân sự', 'Tiếng Anh giao tiếp thực tế trong tuyển dụng & nhân sự', 6),
(7, 'FINANCE', 'Ngân hàng & tài chính', 'Tiếng Anh giao tiếp thực tế trong ngân hàng & tài chính', 7),
(8, 'LOGISTICS', 'Logistics & vận chuyển', 'Tiếng Anh giao tiếp thực tế trong logistics & vận chuyển', 8),
(9, 'HOSPITALITY', 'Khách sạn & sự kiện', 'Tiếng Anh giao tiếp thực tế trong khách sạn & sự kiện', 9),
(10, 'MARKETING', 'Marketing & truyền thông', 'Tiếng Anh giao tiếp thực tế trong marketing & truyền thông', 10);
INSERT INTO lessons (lesson_id,module_id,title,target_situation,order_index) VALUES
(301, 3, 'Báo lỗi đăng nhập và nhờ hỗ trợ IT', 'Người dùng mô tả lỗi đăng nhập cho nhân viên hỗ trợ.', 1),
(302, 3, 'Trao đổi yêu cầu và tiến độ dự án phần mềm', 'Khách hàng và quản lý dự án thống nhất yêu cầu trước khi phát triển.', 2),
(303, 4, 'Đặt lịch khám và trao đổi tại quầy tiếp nhận', 'Người bệnh hỏi lịch khám và giấy tờ cần chuẩn bị.', 3),
(304, 4, 'Hỏi dược sĩ về hướng dẫn trên đơn thuốc', 'Người bệnh nhờ dược sĩ giải thích thông tin đã được bác sĩ chỉ định.', 4),
(305, 5, 'Hỏi thông tin khóa học và đăng ký nhập học', 'Người học hỏi nội dung khóa học, học phí và quy trình đăng ký.', 5),
(306, 5, 'Hỏi giảng viên về bài tập và dự án nhóm', 'Sinh viên làm rõ yêu cầu bài tập và cách phối hợp nhóm.', 6),
(307, 6, 'Phỏng vấn xin việc và giới thiệu kinh nghiệm', 'Ứng viên giới thiệu bản thân và hỏi về vị trí tuyển dụng.', 7),
(308, 6, 'Trao đổi hợp đồng, giờ làm và quyền lợi', 'Ứng viên hỏi nhân sự về điều kiện làm việc trước khi nhận việc.', 8),
(309, 7, 'Mở tài khoản và hỏi phí ngân hàng', 'Khách hàng hỏi ngân hàng về hồ sơ, phí và dịch vụ trực tuyến.', 9),
(310, 7, 'Báo giao dịch lạ và nhờ kiểm tra thẻ', 'Khách hàng liên hệ ngân hàng khi nhận thấy giao dịch chưa rõ.', 10),
(311, 8, 'Đặt lịch lấy hàng và xác nhận chứng từ', 'Doanh nghiệp phối hợp với đơn vị vận chuyển để lấy kiện hàng.', 11),
(312, 8, 'Theo dõi đơn hàng chậm và hỏi thủ tục hải quan', 'Người nhận hỏi đơn vị vận chuyển về tình trạng lô hàng.', 12),
(313, 9, 'Nhờ lễ tân gợi ý hoạt động và đặt dịch vụ', 'Khách hỏi lễ tân các hoạt động gần khách sạn và cách đặt chỗ.', 13),
(314, 9, 'Đặt phòng họp và chuẩn bị sự kiện', 'Khách trao đổi với khách sạn về số người, thiết bị và dịch vụ sự kiện.', 14),
(315, 10, 'Nhận yêu cầu và lập kế hoạch chiến dịch marketing', 'Đối tác và nhân viên marketing làm rõ mục tiêu, đối tượng và ngân sách.', 15),
(316, 10, 'Báo cáo kết quả và nhận phản hồi từ khách hàng', 'Nhân viên marketing trình bày dữ liệu và thảo luận bước cải thiện.', 16);
INSERT INTO phrases (phrase_id,lesson_id,english_text,vietnamese_meaning,ipa_phonetic,audio_sample_url,context_note) VALUES
(30101, 301, 'Hello. What problem are you having?', 'Xin chào. Bạn đang gặp vấn đề gì?', '/hɛˈloʊ. wət ˈprɑbləm ər ju ˈhævɪŋ/', '', 'PRACTICE_SENTENCE'),
(30102, 301, 'I cannot sign in to my account.', 'Tôi không thể đăng nhập vào tài khoản.', '/aɪ ˈkænɑt saɪn ɪn tə maɪ əˈkaʊnt/', '', 'PRACTICE_SENTENCE'),
(30103, 301, 'Do you see an error message?', 'Bạn có thấy thông báo lỗi không?', '/du ju si ən ˈɛrər ˈmɛsɪʤ/', '', 'PRACTICE_SENTENCE'),
(30104, 301, 'password', 'mật khẩu', '/ˈpæsˌwərd/', '', 'VOCABULARY'),
(30105, 301, 'account', 'tài khoản', '/əˈkaʊnt/', '', 'VOCABULARY'),
(30106, 301, 'error', 'lỗi', '/ˈɛrər/', '', 'VOCABULARY'),
(30107, 301, 'It says my password is incorrect.', 'Thông báo nói mật khẩu của tôi không đúng.', '/ɪt sɪz maɪ ˈpæsˌwərd ɪz ˌɪnkərˈɛkt/', '', 'PRACTICE_SENTENCE'),
(30108, 301, 'Have you tried resetting your password?', 'Bạn đã thử đặt lại mật khẩu chưa?', '/hæv ju traɪd riˈsɛtɪŋ jʊr ˈpæsˌwərd/', '', 'PRACTICE_SENTENCE'),
(30109, 301, 'Not yet. Could you guide me through it?', 'Chưa. Bạn hướng dẫn tôi từng bước được không?', '/nɑt jɛt. kʊd ju gaɪd mi θru ɪt/', '', 'PRACTICE_SENTENCE'),
(30110, 301, 'Of course. I will explain the steps.', 'Được chứ. Tôi sẽ giải thích các bước.', '/əv kɔrs. aɪ wɪl ɪkˈspleɪn ðə stɛps/', '', 'PRACTICE_SENTENCE'),
(30111, 301, 'Thank you. I will follow your instructions.', 'Cảm ơn. Tôi sẽ làm theo hướng dẫn.', '/θæŋk ju. aɪ wɪl ˈfɑloʊ jʊr ˌɪnˈstrəkʃənz/', '', 'PRACTICE_SENTENCE'),
(30112, 301, 'Could you send me a screenshot of the error?', 'Bạn gửi ảnh chụp thông báo lỗi giúp tôi nhé?', '/kʊd ju sɛnd mi ə ˈskrinˌʃɑt əv ðə ˈɛrər/', '', 'PRACTICE_SENTENCE'),
(30113, 301, 'Please do not share your password with anyone.', 'Vui lòng không chia sẻ mật khẩu với bất kỳ ai.', '/pliz du nɑt ʃɛr jʊr ˈpæsˌwərd wɪθ ˈɛniˌwən/', '', 'PRACTICE_SENTENCE'),
(30201, 302, 'What would you like the software to do?', 'Bạn muốn phần mềm làm những gì?', '/wət wʊd ju laɪk ðə ˈsɔfˌwɛr tə du/', '', 'PRACTICE_SENTENCE'),
(30202, 302, 'We need a simple booking system.', 'Chúng tôi cần một hệ thống đặt lịch đơn giản.', '/wi nid ə ˈsɪmpəl ˈbʊkɪŋ ˈsɪstəm/', '', 'PRACTICE_SENTENCE'),
(30203, 302, 'Who will use the system?', 'Ai sẽ sử dụng hệ thống?', '/hu wɪl juz ðə ˈsɪstəm/', '', 'PRACTICE_SENTENCE'),
(30204, 302, 'software', 'phần mềm', '/ˈsɔfˌwɛr/', '', 'VOCABULARY'),
(30205, 302, 'requirement', 'yêu cầu', '/rɪkˈwaɪrmənt/', '', 'VOCABULARY'),
(30206, 302, 'deadline', 'thời hạn', '/ˈdɛˌdlaɪn/', '', 'VOCABULARY'),
(30207, 302, 'Our customers and reception staff will use it.', 'Khách hàng và nhân viên lễ tân sẽ sử dụng.', '/ɑr ˈkəstəmərz ənd rɪˈsɛpʃən stæf wɪl juz ɪt/', '', 'PRACTICE_SENTENCE'),
(30208, 302, 'Do you have a deadline in mind?', 'Bạn có thời hạn dự kiến không?', '/du ju hæv ə ˈdɛˌdlaɪn ɪn maɪnd/', '', 'PRACTICE_SENTENCE'),
(30209, 302, 'Could we discuss a realistic timeline?', 'Chúng ta trao đổi về lịch trình khả thi được không?', '/kʊd wi dɪˈskəs ə ˌriəˈlɪstɪk ˈtaɪmlaɪn/', '', 'PRACTICE_SENTENCE'),
(30210, 302, 'Yes. Let us review the requirements first.', 'Được. Trước hết hãy xem lại các yêu cầu.', '/jɛs. lɛt ˈjuˈɛs ˌrivˈju ðə rɪkˈwaɪrmənts fərst/', '', 'PRACTICE_SENTENCE'),
(30211, 302, 'That sounds good. I can share our priorities.', 'Hợp lý đấy. Tôi có thể chia sẻ các ưu tiên.', '/ðət saʊnz gʊd. aɪ kən ʃɛr ɑr praɪˈɔrətiz/', '', 'PRACTICE_SENTENCE'),
(30212, 302, 'Which feature should we build first?', 'Chúng ta nên xây dựng tính năng nào trước?', '/wɪʧ ˈfiʧər ʃʊd wi bɪld fərst/', '', 'PRACTICE_SENTENCE'),
(30213, 302, 'Please let us know if the requirements change.', 'Vui lòng báo nếu các yêu cầu thay đổi.', '/pliz lɛt ˈjuˈɛs noʊ ɪf ðə rɪkˈwaɪrmənts ʧeɪnʤ/', '', 'PRACTICE_SENTENCE'),
(30301, 303, 'Hello. How can I help you?', 'Xin chào. Tôi có thể giúp gì cho bạn?', '/hɛˈloʊ. haʊ kən aɪ hɛlp ju/', '', 'PRACTICE_SENTENCE'),
(30302, 303, 'I would like to make an appointment.', 'Tôi muốn đặt lịch khám.', '/aɪ wʊd laɪk tə meɪk ən əˈpɔɪntmənt/', '', 'PRACTICE_SENTENCE'),
(30303, 303, 'Would you prefer a morning or afternoon visit?', 'Bạn muốn khám buổi sáng hay buổi chiều?', '/wʊd ju prɪˈfər ə ˈmɔrnɪŋ ər ˌæftərˈnun ˈvɪzɪt/', '', 'PRACTICE_SENTENCE'),
(30304, 303, 'appointment', 'lịch hẹn', '/əˈpɔɪntmənt/', '', 'VOCABULARY'),
(30305, 303, 'insurance', 'bảo hiểm', '/ˌɪnˈʃʊrəns/', '', 'VOCABULARY'),
(30306, 303, 'identification', 'giấy tờ tùy thân', '/aɪˌdɛntəfəˈkeɪʃən/', '', 'VOCABULARY'),
(30307, 303, 'A morning appointment would be better.', 'Một lịch hẹn buổi sáng sẽ phù hợp hơn.', '/ə ˈmɔrnɪŋ əˈpɔɪntmənt wʊd bi ˈbɛtər/', '', 'PRACTICE_SENTENCE'),
(30308, 303, 'Do you have your insurance details with you?', 'Bạn có mang thông tin bảo hiểm không?', '/du ju hæv jʊr ˌɪnˈʃʊrəns ˈditeɪlz wɪθ ju/', '', 'PRACTICE_SENTENCE'),
(30309, 303, 'Yes. Which documents should I bring?', 'Có. Tôi nên mang những giấy tờ nào?', '/jɛs. wɪʧ ˈdɑkjəmənts ʃʊd aɪ brɪŋ/', '', 'PRACTICE_SENTENCE'),
(30310, 303, 'Please bring your identification and relevant records.', 'Vui lòng mang giấy tờ tùy thân và hồ sơ liên quan.', '/pliz brɪŋ jʊr aɪˌdɛntəfəˈkeɪʃən ənd ˈrɛləvənt ˈrɛkərdz/', '', 'PRACTICE_SENTENCE'),
(30311, 303, 'Thank you. Could you confirm the appointment time?', 'Cảm ơn. Bạn xác nhận giờ hẹn giúp tôi nhé?', '/θæŋk ju. kʊd ju kənˈfərm ðə əˈpɔɪntmənt taɪm/', '', 'PRACTICE_SENTENCE'),
(30312, 303, 'Where should I wait when I arrive?', 'Khi đến tôi nên chờ ở đâu?', '/wɛr ʃʊd aɪ weɪt wɪn aɪ əraɪv/', '', 'PRACTICE_SENTENCE'),
(30313, 303, 'Could you repeat the instructions more slowly?', 'Bạn nhắc lại hướng dẫn chậm hơn được không?', '/kʊd ju rɪˈpit ðə ˌɪnˈstrəkʃənz mɔr sˈloʊli/', '', 'PRACTICE_SENTENCE'),
(30401, 304, 'Do you have a prescription?', 'Bạn có đơn thuốc không?', '/du ju hæv ə prəˈskrɪpʃən/', '', 'PRACTICE_SENTENCE'),
(30402, 304, 'Yes. Could you help me read these instructions?', 'Có. Bạn giúp tôi đọc hướng dẫn này nhé?', '/jɛs. kʊd ju hɛlp mi rɛd ðiz ˌɪnˈstrəkʃənz/', '', 'PRACTICE_SENTENCE'),
(30403, 304, 'Which part would you like me to explain?', 'Bạn muốn tôi giải thích phần nào?', '/wɪʧ pɑrt wʊd ju laɪk mi tə ɪkˈspleɪn/', '', 'PRACTICE_SENTENCE'),
(30404, 304, 'prescription', 'đơn thuốc', '/prəˈskrɪpʃən/', '', 'VOCABULARY'),
(30405, 304, 'label', 'nhãn', '/ˈleɪbəl/', '', 'VOCABULARY'),
(30406, 304, 'pharmacy', 'nhà thuốc', '/ˈfɑrməsi/', '', 'VOCABULARY'),
(30407, 304, 'I am not sure what this label means.', 'Tôi chưa hiểu nhãn này có nghĩa gì.', '/aɪ æm nɑt ʃʊr wət ðɪs ˈleɪbəl minz/', '', 'PRACTICE_SENTENCE'),
(30408, 304, 'I can explain the label and check with the pharmacist.', 'Tôi có thể giải thích nhãn và kiểm tra với dược sĩ.', '/aɪ kən ɪkˈspleɪn ðə ˈleɪbəl ənd ʧɛk wɪθ ðə ˈfɑrməsɪst/', '', 'PRACTICE_SENTENCE'),
(30409, 304, 'Please also tell me who to contact with questions.', 'Vui lòng cho tôi biết nên liên hệ ai nếu có thắc mắc.', '/pliz ˈɔlsoʊ tɛl mi hu tə ˈkɑnˌtækt wɪθ kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(30410, 304, 'You can contact the pharmacy or your doctor.', 'Bạn có thể liên hệ nhà thuốc hoặc bác sĩ.', '/ju kən ˈkɑnˌtækt ðə ˈfɑrməsi ər jʊr ˈdɔktər/', '', 'PRACTICE_SENTENCE'),
(30411, 304, 'Thank you. I will ask before changing anything.', 'Cảm ơn. Tôi sẽ hỏi trước khi thay đổi điều gì.', '/θæŋk ju. aɪ wɪl æsk ˌbiˈfɔr ˈʧeɪnʤɪŋ ˈɛniˌθɪŋ/', '', 'PRACTICE_SENTENCE'),
(30412, 304, 'I have an allergy that I need to mention.', 'Tôi có tình trạng dị ứng cần báo.', '/aɪ hæv ən ˈælərʤi ðət aɪ nid tə ˈmɛnʃən/', '', 'PRACTICE_SENTENCE'),
(30413, 304, 'Could you write the instructions down for me?', 'Bạn viết hướng dẫn ra giúp tôi nhé?', '/kʊd ju raɪt ðə ˌɪnˈstrəkʃənz daʊn fər mi/', '', 'PRACTICE_SENTENCE'),
(30501, 305, 'Which course are you interested in?', 'Bạn quan tâm khóa học nào?', '/wɪʧ kɔrs ər ju ˈɪntəˌrɛstɪd ɪn/', '', 'PRACTICE_SENTENCE'),
(30502, 305, 'I would like to learn about the evening classes.', 'Tôi muốn tìm hiểu các lớp buổi tối.', '/aɪ wʊd laɪk tə lərn əˈbaʊt ðə ˈivnɪŋ ˈklæsɪz/', '', 'PRACTICE_SENTENCE'),
(30503, 305, 'What is your current level?', 'Trình độ hiện tại của bạn thế nào?', '/wət ɪz jʊr ˈkɑrənt ˈlɛvəl/', '', 'PRACTICE_SENTENCE'),
(30504, 305, 'course', 'khóa học', '/kɔrs/', '', 'VOCABULARY'),
(30505, 305, 'tuition', 'học phí', '/tjuˈɪʃən/', '', 'VOCABULARY'),
(30506, 305, 'campus', 'khuôn viên trường', '/ˈkæmpəs/', '', 'VOCABULARY'),
(30507, 305, 'I am a beginner and need a practical course.', 'Tôi mới bắt đầu và cần khóa học thực tế.', '/aɪ æm ə bɪˈgɪnər ənd nid ə ˈpræktɪkəl kɔrs/', '', 'PRACTICE_SENTENCE'),
(30508, 305, 'Would you like information about the fees?', 'Bạn muốn biết thông tin học phí không?', '/wʊd ju laɪk ˌɪnˌfɔrˈmeɪʃən əˈbaʊt ðə fiz/', '', 'PRACTICE_SENTENCE'),
(30509, 305, 'Yes. Could you explain the total cost?', 'Có. Bạn giải thích tổng chi phí giúp tôi nhé?', '/jɛs. kʊd ju ɪkˈspleɪn ðə ˈtoʊtəl kɔst/', '', 'PRACTICE_SENTENCE'),
(30510, 305, 'I can send you the course details and application steps.', 'Tôi có thể gửi thông tin khóa học và các bước đăng ký.', '/aɪ kən sɛnd ju ðə kɔrs ˈditeɪlz ənd ˌæpləˈkeɪʃən stɛps/', '', 'PRACTICE_SENTENCE'),
(30511, 305, 'Thank you. What documents do I need to apply?', 'Cảm ơn. Tôi cần giấy tờ gì để đăng ký?', '/θæŋk ju. wət ˈdɑkjəmənts du aɪ nid tə əˈplaɪ/', '', 'PRACTICE_SENTENCE'),
(30512, 305, 'Are there any classes on weekends?', 'Có lớp học cuối tuần không?', '/ər ðɛr ˈɛni ˈklæsɪz ɔn ˈwiˌkɛndz/', '', 'PRACTICE_SENTENCE'),
(30513, 305, 'Could I visit the campus before registering?', 'Tôi có thể đến thăm trường trước khi đăng ký không?', '/kʊd aɪ ˈvɪzɪt ðə ˈkæmpəs ˌbiˈfɔr ˈrɛʤɪstərɪŋ/', '', 'PRACTICE_SENTENCE'),
(30601, 306, 'Do you have a question about the assignment?', 'Bạn có câu hỏi về bài tập không?', '/du ju hæv ə kˈwɛʃən əˈbaʊt ðə əˈsaɪnmənt/', '', 'PRACTICE_SENTENCE'),
(30602, 306, 'Could you explain what we need to submit?', 'Thầy/cô giải thích chúng em cần nộp gì nhé?', '/kʊd ju ɪkˈspleɪn wət wi nid tə səbˈmɪt/', '', 'PRACTICE_SENTENCE'),
(30603, 306, 'You need to prepare a short group presentation.', 'Các em cần chuẩn bị một bài thuyết trình nhóm ngắn.', '/ju nid tə priˈpɛr ə ʃɔrt grup ˌprɛzənˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
(30604, 306, 'assignment', 'bài tập được giao', '/əˈsaɪnmənt/', '', 'VOCABULARY'),
(30605, 306, 'presentation', 'bài thuyết trình', '/ˌprɛzənˈteɪʃən/', '', 'VOCABULARY'),
(30606, 306, 'feedback', 'phản hồi, góp ý', '/ˈfidˌbæk/', '', 'VOCABULARY'),
(30607, 306, 'How many students should be in each group?', 'Mỗi nhóm nên có bao nhiêu sinh viên?', '/haʊ ˈmɛni ˈstudənts ʃʊd bi ɪn iʧ grup/', '', 'PRACTICE_SENTENCE'),
(30608, 306, 'Please check the instructions for the group size.', 'Hãy xem hướng dẫn về số thành viên mỗi nhóm.', '/pliz ʧɛk ðə ˌɪnˈstrəkʃənz fər ðə grup saɪz/', '', 'PRACTICE_SENTENCE'),
(30609, 306, 'Where can we find the marking criteria?', 'Chúng em tìm tiêu chí chấm điểm ở đâu?', '/wɛr kən wi faɪnd ðə ˈmɑrkɪŋ kraɪˈtɪriə/', '', 'PRACTICE_SENTENCE'),
