(31309, 313, 'Could you tell me the price before booking?', 'Bạn cho tôi biết giá trước khi đặt nhé?', '/kʊd ju tɛl mi ðə praɪs ˌbiˈfɔr ˈbʊkɪŋ/', '', 'PRACTICE_SENTENCE'),
(31310, 313, 'Of course. I will confirm the details first.', 'Được chứ. Tôi sẽ xác nhận thông tin trước.', '/əv kɔrs. aɪ wɪl kənˈfərm ðə ˈditeɪlz fərst/', '', 'PRACTICE_SENTENCE'),
(31311, 313, 'Thank you. Please include the meeting point.', 'Cảm ơn. Vui lòng cho biết cả điểm tập trung.', '/θæŋk ju. pliz ˌɪnˈklud ðə ˈmitɪŋ pɔɪnt/', '', 'PRACTICE_SENTENCE'),
(31312, 313, 'Can you help me arrange transport to the meeting point?', 'Bạn giúp tôi sắp xếp phương tiện đến điểm tập trung nhé?', '/kən ju hɛlp mi əreɪnʤ ˈtrænspɔrt tə ðə ˈmitɪŋ pɔɪnt/', '', 'PRACTICE_SENTENCE'),
(31313, 313, 'What is the cancellation policy for this booking?', 'Chính sách hủy cho đặt chỗ này là gì?', '/wət ɪz ðə ˌkænsəˈleɪʃən ˈpɑləsi fər ðɪs ˈbʊkɪŋ/', '', 'PRACTICE_SENTENCE'),
(31401, 314, 'What kind of event are you planning?', 'Bạn dự định tổ chức sự kiện nào?', '/wət kaɪnd əv ɪˈvɛnt ər ju ˈplænɪŋ/', '', 'PRACTICE_SENTENCE'),
(31402, 314, 'We are planning a small business meeting.', 'Chúng tôi dự định tổ chức cuộc họp doanh nghiệp nhỏ.', '/wi ər ˈplænɪŋ ə smɔl ˈbɪznɪs ˈmitɪŋ/', '', 'PRACTICE_SENTENCE'),
(31403, 314, 'How many people do you expect?', 'Bạn dự kiến có bao nhiêu người?', '/haʊ ˈmɛni ˈpipəl du ju ɪkˈspɛkt/', '', 'PRACTICE_SENTENCE'),
(31404, 314, 'participant', 'người tham gia', '/pɑrˈtɪsəpənt/', '', 'VOCABULARY'),
(31405, 314, 'projector', 'máy chiếu', '/prɑˈʤɛktər/', '', 'VOCABULARY'),
(31406, 314, 'catering', 'dịch vụ ăn uống', '/ˈkeɪtərɪŋ/', '', 'VOCABULARY'),
(31407, 314, 'We expect around twenty participants.', 'Chúng tôi dự kiến khoảng hai mươi người.', '/wi ɪkˈspɛkt əraʊnd tˈwɛnti pɑrˈtɪsəpənts/', '', 'PRACTICE_SENTENCE'),
(31408, 314, 'Do you need any presentation equipment?', 'Bạn cần thiết bị thuyết trình không?', '/du ju nid ˈɛni ˌprɛzənˈteɪʃən ɪkˈwɪpmənt/', '', 'PRACTICE_SENTENCE'),
(31409, 314, 'We need a projector and reliable internet access.', 'Chúng tôi cần máy chiếu và kết nối internet ổn định.', '/wi nid ə prɑˈʤɛktər ənd rɪˈlaɪəbəl ˈɪntərˌnɛt ˈækˌsɛs/', '', 'PRACTICE_SENTENCE'),
(31410, 314, 'I can prepare a quotation based on your requirements.', 'Tôi có thể chuẩn bị báo giá theo yêu cầu của bạn.', '/aɪ kən priˈpɛr ə kwoʊˈteɪʃən beɪst ɔn jʊr rɪkˈwaɪrmənts/', '', 'PRACTICE_SENTENCE'),
(31411, 314, 'Thank you. Please include any additional fees.', 'Cảm ơn. Vui lòng tính cả các khoản phí bổ sung.', '/θæŋk ju. pliz ˌɪnˈklud ˈɛni əˈdɪʃənəl fiz/', '', 'PRACTICE_SENTENCE'),
(31412, 314, 'Could you show us the room layout?', 'Bạn cho chúng tôi xem cách bố trí phòng nhé?', '/kʊd ju ʃoʊ ˈjuˈɛs ðə rum leɪaʊt/', '', 'PRACTICE_SENTENCE'),
(31413, 314, 'Is catering available during the meeting?', 'Có dịch vụ ăn uống trong cuộc họp không?', '/ɪz ˈkeɪtərɪŋ əˈveɪləbəl ˈdʊrɪŋ ðə ˈmitɪŋ/', '', 'PRACTICE_SENTENCE'),
(31501, 315, 'What is the main goal of this campaign?', 'Mục tiêu chính của chiến dịch này là gì?', '/wət ɪz ðə meɪn goʊl əv ðɪs kæmˈpeɪn/', '', 'PRACTICE_SENTENCE'),
(31502, 315, 'We want more people to know about our new service.', 'Chúng tôi muốn nhiều người biết đến dịch vụ mới.', '/wi wɔnt mɔr ˈpipəl tə noʊ əˈbaʊt ɑr nu ˈsərvɪs/', '', 'PRACTICE_SENTENCE'),
(31503, 315, 'Who is your target audience?', 'Đối tượng khách hàng mục tiêu của bạn là ai?', '/hu ɪz jʊr ˈtərgət ˈɔdiəns/', '', 'PRACTICE_SENTENCE'),
(31504, 315, 'campaign', 'chiến dịch', '/kæmˈpeɪn/', '', 'VOCABULARY'),
(31505, 315, 'audience', 'đối tượng khán giả', '/ˈɔdiəns/', '', 'VOCABULARY'),
(31506, 315, 'proposal', 'đề xuất', '/prəˈpoʊzəl/', '', 'VOCABULARY'),
(31507, 315, 'We are focusing on working adults.', 'Chúng tôi tập trung vào người trưởng thành đi làm.', '/wi ər ˈfoʊkɪsɪŋ ɔn ˈwərkɪŋ ˈædəlts/', '', 'PRACTICE_SENTENCE'),
(31508, 315, 'Do you have a budget for the campaign?', 'Bạn có ngân sách cho chiến dịch không?', '/du ju hæv ə ˈbəʤɪt fər ðə kæmˈpeɪn/', '', 'PRACTICE_SENTENCE'),
(31509, 315, 'Could you suggest options at different price levels?', 'Bạn gợi ý các lựa chọn ở nhiều mức giá nhé?', '/kʊd ju səˈʤɛst ˈɔpʃənz æt ˈdɪfərənt praɪs ˈlɛvəlz/', '', 'PRACTICE_SENTENCE'),
(31510, 315, 'Yes. I will prepare a proposal for you.', 'Được. Tôi sẽ chuẩn bị đề xuất cho bạn.', '/jɛs. aɪ wɪl priˈpɛr ə prəˈpoʊzəl fər ju/', '', 'PRACTICE_SENTENCE'),
(31511, 315, 'Thank you. Please explain how we will measure success.', 'Cảm ơn. Vui lòng giải thích cách đo lường thành công.', '/θæŋk ju. pliz ɪkˈspleɪn haʊ wi wɪl ˈmɛʒər səkˈsɛs/', '', 'PRACTICE_SENTENCE'),
(31512, 315, 'Which channels would you recommend for this audience?', 'Bạn gợi ý các kênh nào cho nhóm khách hàng này?', '/wɪʧ ˈʧænəlz wʊd ju ˌrɛkəˈmɛnd fər ðɪs ˈɔdiəns/', '', 'PRACTICE_SENTENCE'),
(31513, 315, 'When can we review the first draft of the plan?', 'Khi nào chúng ta xem bản nháp kế hoạch đầu tiên?', '/wɪn kən wi ˌrivˈju ðə fərst dræft əv ðə plæn/', '', 'PRACTICE_SENTENCE'),
(31601, 316, 'Would you like an overview of the results?', 'Bạn muốn xem tổng quan kết quả không?', '/wʊd ju laɪk ən ˈoʊvərvˌju əv ðə rɪˈzəlts/', '', 'PRACTICE_SENTENCE'),
(31602, 316, 'Yes. Which numbers should we focus on?', 'Có. Chúng ta nên tập trung vào số liệu nào?', '/jɛs. wɪʧ ˈnəmbərz ʃʊd wi ˈfoʊkɪs ɔn/', '', 'PRACTICE_SENTENCE'),
(31603, 316, 'We can compare reach, engagement and enquiries.', 'Chúng ta có thể so sánh độ tiếp cận, tương tác và lượt hỏi thông tin.', '/wi kən kəmˈpɛr riʧ, ɛnˈgeɪʤmənt ənd ɪnˈkwaɪəriz/', '', 'PRACTICE_SENTENCE'),
(31604, 316, 'engagement', 'mức độ tương tác', '/ɛnˈgeɪʤmənt/', '', 'VOCABULARY'),
(31605, 316, 'report', 'báo cáo', '/rɪˈpɔrt/', '', 'VOCABULARY'),
(31606, 316, 'measure', 'chỉ số, phép đo', '/ˈmɛʒər/', '', 'VOCABULARY'),
(31607, 316, 'Could you explain what those figures mean?', 'Bạn giải thích ý nghĩa các số liệu đó nhé?', '/kʊd ju ɪkˈspleɪn wət ðoʊz ˈfɪgjərz min/', '', 'PRACTICE_SENTENCE'),
(31608, 316, 'I will explain each measure and its limitations.', 'Tôi sẽ giải thích từng chỉ số và giới hạn của nó.', '/aɪ wɪl ɪkˈspleɪn iʧ ˈmɛʒər ənd ɪts ˌlɪmɪˈteɪʃənz/', '', 'PRACTICE_SENTENCE'),
(31609, 316, 'What could we improve in the next campaign?', 'Chúng ta có thể cải thiện gì ở chiến dịch tiếp theo?', '/wət kʊd wi ˌɪmˈpruv ɪn ðə nɛkst kæmˈpeɪn/', '', 'PRACTICE_SENTENCE'),
(31610, 316, 'Let us review the feedback before making changes.', 'Hãy xem phản hồi trước khi thay đổi.', '/lɛt ˈjuˈɛs ˌrivˈju ðə ˈfidˌbæk ˌbiˈfɔr ˈmeɪkɪŋ ˈʧeɪnʤɪz/', '', 'PRACTICE_SENTENCE'),
(31611, 316, 'That sounds good. Please send me the report.', 'Hợp lý đấy. Vui lòng gửi báo cáo cho tôi.', '/ðət saʊnz gʊd. pliz sɛnd mi ðə rɪˈpɔrt/', '', 'PRACTICE_SENTENCE'),
(31612, 316, 'How does this compare with the previous campaign?', 'Kết quả này so với chiến dịch trước thế nào?', '/haʊ dɪz ðɪs kəmˈpɛr wɪθ ðə ˈpriviəs kæmˈpeɪn/', '', 'PRACTICE_SENTENCE'),
(31613, 316, 'Could we schedule a meeting to discuss the next steps?', 'Chúng ta đặt lịch họp để trao đổi bước tiếp theo nhé?', '/kʊd wi ˈskɛʤʊl ə ˈmitɪŋ tə dɪˈskəs ðə nɛkst stɛps/', '', 'PRACTICE_SENTENCE');
INSERT INTO scenarios (scenario_id,lesson_id,title,ai_role_name,user_role_name,context_briefing,initial_ai_greeting,illustration_key,illustration_alt,partner_name,learner_name) VALUES
(535, 301, 'Báo lỗi đăng nhập và nhờ hỗ trợ IT', 'Nhân viên IT', 'Người dùng', 'Người dùng mô tả lỗi đăng nhập cho nhân viên hỗ trợ.', 'Hello. What problem are you having?', 'phone', 'Người dùng mô tả lỗi đăng nhập cho nhân viên hỗ trợ.', 'Alex', 'Minh'),
(536, 302, 'Trao đổi yêu cầu và tiến độ dự án phần mềm', 'Quản lý dự án', 'Khách hàng', 'Khách hàng và quản lý dự án thống nhất yêu cầu trước khi phát triển.', 'What would you like the software to do?', 'office', 'Khách hàng và quản lý dự án thống nhất yêu cầu trước khi phát triển.', 'Emma', 'Lan'),
(537, 303, 'Đặt lịch khám và trao đổi tại quầy tiếp nhận', 'Nhân viên tiếp nhận', 'Người bệnh', 'Người bệnh hỏi lịch khám và giấy tờ cần chuẩn bị.', 'Hello. How can I help you?', 'office', 'Người bệnh hỏi lịch khám và giấy tờ cần chuẩn bị.', 'Taylor', 'Minh'),
(538, 304, 'Hỏi dược sĩ về hướng dẫn trên đơn thuốc', 'Dược sĩ', 'Người bệnh', 'Người bệnh nhờ dược sĩ giải thích thông tin đã được bác sĩ chỉ định.', 'Do you have a prescription?', 'retail', 'Người bệnh nhờ dược sĩ giải thích thông tin đã được bác sĩ chỉ định.', 'Grace', 'Lan'),
(539, 305, 'Hỏi thông tin khóa học và đăng ký nhập học', 'Nhân viên tuyển sinh', 'Người học', 'Người học hỏi nội dung khóa học, học phí và quy trình đăng ký.', 'Which course are you interested in?', 'office', 'Người học hỏi nội dung khóa học, học phí và quy trình đăng ký.', 'Alex', 'Minh'),
(540, 306, 'Hỏi giảng viên về bài tập và dự án nhóm', 'Giảng viên', 'Sinh viên', 'Sinh viên làm rõ yêu cầu bài tập và cách phối hợp nhóm.', 'Do you have a question about the assignment?', 'office', 'Sinh viên làm rõ yêu cầu bài tập và cách phối hợp nhóm.', 'Emma', 'Lan'),
(541, 307, 'Phỏng vấn xin việc và giới thiệu kinh nghiệm', 'Nhà tuyển dụng', 'Ứng viên', 'Ứng viên giới thiệu bản thân và hỏi về vị trí tuyển dụng.', 'Could you tell me about yourself?', 'office', 'Ứng viên giới thiệu bản thân và hỏi về vị trí tuyển dụng.', 'Taylor', 'Minh'),
(542, 308, 'Trao đổi hợp đồng, giờ làm và quyền lợi', 'Nhân viên nhân sự', 'Ứng viên', 'Ứng viên hỏi nhân sự về điều kiện làm việc trước khi nhận việc.', 'Would you like to review the job offer?', 'office', 'Ứng viên hỏi nhân sự về điều kiện làm việc trước khi nhận việc.', 'Grace', 'Lan'),
(543, 309, 'Mở tài khoản và hỏi phí ngân hàng', 'Nhân viên ngân hàng', 'Khách hàng', 'Khách hàng hỏi ngân hàng về hồ sơ, phí và dịch vụ trực tuyến.', 'How can I help you today?', 'office', 'Khách hàng hỏi ngân hàng về hồ sơ, phí và dịch vụ trực tuyến.', 'Alex', 'Minh'),
(544, 310, 'Báo giao dịch lạ và nhờ kiểm tra thẻ', 'Nhân viên ngân hàng', 'Chủ thẻ', 'Khách hàng liên hệ ngân hàng khi nhận thấy giao dịch chưa rõ.', 'What seems to be the problem?', 'phone', 'Khách hàng liên hệ ngân hàng khi nhận thấy giao dịch chưa rõ.', 'Emma', 'Lan'),
(545, 311, 'Đặt lịch lấy hàng và xác nhận chứng từ', 'Điều phối vận chuyển', 'Người gửi hàng', 'Doanh nghiệp phối hợp với đơn vị vận chuyển để lấy kiện hàng.', 'When will the shipment be ready?', 'packing', 'Doanh nghiệp phối hợp với đơn vị vận chuyển để lấy kiện hàng.', 'Taylor', 'Minh'),
(546, 312, 'Theo dõi đơn hàng chậm và hỏi thủ tục hải quan', 'Nhân viên vận chuyển', 'Người nhận', 'Người nhận hỏi đơn vị vận chuyển về tình trạng lô hàng.', 'Could I have your tracking number?', 'phone', 'Người nhận hỏi đơn vị vận chuyển về tình trạng lô hàng.', 'Grace', 'Lan'),
(547, 313, 'Nhờ lễ tân gợi ý hoạt động và đặt dịch vụ', 'Nhân viên lễ tân', 'Khách lưu trú', 'Khách hỏi lễ tân các hoạt động gần khách sạn và cách đặt chỗ.', 'Good morning. How can I help?', 'hotel', 'Khách hỏi lễ tân các hoạt động gần khách sạn và cách đặt chỗ.', 'Alex', 'Minh'),
(548, 314, 'Đặt phòng họp và chuẩn bị sự kiện', 'Điều phối sự kiện', 'Người tổ chức', 'Khách trao đổi với khách sạn về số người, thiết bị và dịch vụ sự kiện.', 'What kind of event are you planning?', 'office', 'Khách trao đổi với khách sạn về số người, thiết bị và dịch vụ sự kiện.', 'Emma', 'Lan'),
(549, 315, 'Nhận yêu cầu và lập kế hoạch chiến dịch marketing', 'Chuyên viên marketing', 'Khách hàng', 'Đối tác và nhân viên marketing làm rõ mục tiêu, đối tượng và ngân sách.', 'What is the main goal of this campaign?', 'office', 'Đối tác và nhân viên marketing làm rõ mục tiêu, đối tượng và ngân sách.', 'Taylor', 'Minh'),
(550, 316, 'Báo cáo kết quả và nhận phản hồi từ khách hàng', 'Chuyên viên marketing', 'Khách hàng', 'Nhân viên marketing trình bày dữ liệu và thảo luận bước cải thiện.', 'Would you like an overview of the results?', 'office', 'Nhân viên marketing trình bày dữ liệu và thảo luận bước cải thiện.', 'Grace', 'Lan');
INSERT INTO scenario_turns (scenario_id,step_order,expected_user_intent,bot_reaction_rules) VALUES
(535, 1, 'I cannot sign in to my account.', 'Hello. What problem are you having?'),
(535, 2, 'It says my password is incorrect.', 'Do you see an error message?'),
(535, 3, 'Not yet. Could you guide me through it?', 'Have you tried resetting your password?'),
(535, 4, 'Thank you. I will follow your instructions.', 'Of course. I will explain the steps.'),
(536, 1, 'We need a simple booking system.', 'What would you like the software to do?'),
(536, 2, 'Our customers and reception staff will use it.', 'Who will use the system?'),
(536, 3, 'Could we discuss a realistic timeline?', 'Do you have a deadline in mind?'),
(536, 4, 'That sounds good. I can share our priorities.', 'Yes. Let us review the requirements first.'),
(537, 1, 'I would like to make an appointment.', 'Hello. How can I help you?'),
(537, 2, 'A morning appointment would be better.', 'Would you prefer a morning or afternoon visit?'),
(537, 3, 'Yes. Which documents should I bring?', 'Do you have your insurance details with you?'),
(537, 4, 'Thank you. Could you confirm the appointment time?', 'Please bring your identification and relevant records.'),
(538, 1, 'Yes. Could you help me read these instructions?', 'Do you have a prescription?'),
(538, 2, 'I am not sure what this label means.', 'Which part would you like me to explain?'),
(538, 3, 'Please also tell me who to contact with questions.', 'I can explain the label and check with the pharmacist.'),
(538, 4, 'Thank you. I will ask before changing anything.', 'You can contact the pharmacy or your doctor.'),
(539, 1, 'I would like to learn about the evening classes.', 'Which course are you interested in?'),
(539, 2, 'I am a beginner and need a practical course.', 'What is your current level?'),
(539, 3, 'Yes. Could you explain the total cost?', 'Would you like information about the fees?'),
(539, 4, 'Thank you. What documents do I need to apply?', 'I can send you the course details and application steps.'),
(540, 1, 'Could you explain what we need to submit?', 'Do you have a question about the assignment?'),
(540, 2, 'How many students should be in each group?', 'You need to prepare a short group presentation.'),
(540, 3, 'Where can we find the marking criteria?', 'Please check the instructions for the group size.'),
(540, 4, 'Thank you. We will review them before starting.', 'They are included in the assignment document.'),
(541, 1, 'I have experience in customer service.', 'Could you tell me about yourself?'),
(541, 2, 'I communicate clearly and enjoy solving problems.', 'What are your main strengths?'),
(541, 3, 'I would like to develop my skills in an international team.', 'Why are you interested in this position?'),
(541, 4, 'Could you describe the daily responsibilities?', 'Do you have any questions for us?'),
(542, 1, 'Yes. Could you explain the working hours?', 'Would you like to review the job offer?'),
(542, 2, 'Are there any flexible working options?', 'The schedule is described in the contract.'),
(542, 3, 'Could you also explain the benefits package?', 'We can discuss the options with the manager.'),
(542, 4, 'Thank you. I would like time to review them.', 'I will send you the written details.'),
(543, 1, 'I would like to open a bank account.', 'How can I help you today?'),
(543, 2, 'I need an account for my everyday expenses.', 'What type of account do you need?'),
(543, 3, 'Yes. Are there any monthly charges?', 'Would you like information about the fees?'),
(543, 4, 'Thank you. Can I manage the account online?', 'I can explain the current terms and required documents.'),
(544, 1, 'I do not recognize this transaction.', 'What seems to be the problem?'),
(544, 2, 'I saw it on my statement this morning.', 'When did you notice it?'),
(544, 3, 'Should I request that the card be blocked?', 'We can explain how to report the transaction securely.'),
(544, 4, 'Thank you. Please explain the next steps.', 'Please follow our secure verification process first.'),
(545, 1, 'The boxes will be ready tomorrow morning.', 'When will the shipment be ready?'),
(545, 2, 'I will send the warehouse address by email.', 'Could you confirm the pickup address?'),
(545, 3, 'Yes. Please let me know if anything else is required.', 'Do you have the invoice and packing list?'),
(545, 4, 'Thank you. Could you confirm the pickup window?', 'We will review the documents before confirming collection.'),
(546, 1, 'Here it is. The delivery seems to be delayed.', 'Could I have your tracking number?'),
(546, 2, 'Is the shipment waiting for customs clearance?', 'Let me check the latest update.'),
(546, 3, 'Do you need any documents from me?', 'We need to confirm that with the relevant team.'),
(546, 4, 'Thank you. Please keep me informed.', 'I will let you know after checking.'),
(547, 1, 'Could you recommend something to do nearby?', 'Good morning. How can I help?'),
(547, 2, 'A local walking tour would be nice.', 'Would you prefer a tour or a quiet activity?'),
(547, 3, 'Could you tell me the price before booking?', 'I can check the available options.'),
(547, 4, 'Thank you. Please include the meeting point.', 'Of course. I will confirm the details first.'),
(548, 1, 'We are planning a small business meeting.', 'What kind of event are you planning?'),
(548, 2, 'We expect around twenty participants.', 'How many people do you expect?'),
(548, 3, 'We need a projector and reliable internet access.', 'Do you need any presentation equipment?'),
(548, 4, 'Thank you. Please include any additional fees.', 'I can prepare a quotation based on your requirements.'),
(549, 1, 'We want more people to know about our new service.', 'What is the main goal of this campaign?'),
(549, 2, 'We are focusing on working adults.', 'Who is your target audience?'),
(549, 3, 'Could you suggest options at different price levels?', 'Do you have a budget for the campaign?'),
(549, 4, 'Thank you. Please explain how we will measure success.', 'Yes. I will prepare a proposal for you.'),
(550, 1, 'Yes. Which numbers should we focus on?', 'Would you like an overview of the results?'),
(550, 2, 'Could you explain what those figures mean?', 'We can compare reach, engagement and enquiries.'),
(550, 3, 'What could we improve in the next campaign?', 'I will explain each measure and its limitations.'),
(550, 4, 'That sounds good. Please send me the report.', 'Let us review the feedback before making changes.');
INSERT INTO dialogue_lines (scenario_id,position,speaker,english_text,vietnamese_text) VALUES
(535, 1, 'partner', 'Hello. What problem are you having?', 'Xin chào. Bạn đang gặp vấn đề gì?'),
(535, 2, 'learner', 'I cannot sign in to my account.', 'Tôi không thể đăng nhập vào tài khoản.'),
(535, 3, 'partner', 'Do you see an error message?', 'Bạn có thấy thông báo lỗi không?'),
(535, 4, 'learner', 'It says my password is incorrect.', 'Thông báo nói mật khẩu của tôi không đúng.'),
(535, 5, 'partner', 'Have you tried resetting your password?', 'Bạn đã thử đặt lại mật khẩu chưa?'),
(535, 6, 'learner', 'Not yet. Could you guide me through it?', 'Chưa. Bạn hướng dẫn tôi từng bước được không?'),
(535, 7, 'partner', 'Of course. I will explain the steps.', 'Được chứ. Tôi sẽ giải thích các bước.'),
(535, 8, 'learner', 'Thank you. I will follow your instructions.', 'Cảm ơn. Tôi sẽ làm theo hướng dẫn.'),
(536, 1, 'partner', 'What would you like the software to do?', 'Bạn muốn phần mềm làm những gì?'),
(536, 2, 'learner', 'We need a simple booking system.', 'Chúng tôi cần một hệ thống đặt lịch đơn giản.'),
(536, 3, 'partner', 'Who will use the system?', 'Ai sẽ sử dụng hệ thống?'),
(536, 4, 'learner', 'Our customers and reception staff will use it.', 'Khách hàng và nhân viên lễ tân sẽ sử dụng.'),
(536, 5, 'partner', 'Do you have a deadline in mind?', 'Bạn có thời hạn dự kiến không?'),
(536, 6, 'learner', 'Could we discuss a realistic timeline?', 'Chúng ta trao đổi về lịch trình khả thi được không?'),
(536, 7, 'partner', 'Yes. Let us review the requirements first.', 'Được. Trước hết hãy xem lại các yêu cầu.'),
(536, 8, 'learner', 'That sounds good. I can share our priorities.', 'Hợp lý đấy. Tôi có thể chia sẻ các ưu tiên.'),
(537, 1, 'partner', 'Hello. How can I help you?', 'Xin chào. Tôi có thể giúp gì cho bạn?'),
(537, 2, 'learner', 'I would like to make an appointment.', 'Tôi muốn đặt lịch khám.'),
(537, 3, 'partner', 'Would you prefer a morning or afternoon visit?', 'Bạn muốn khám buổi sáng hay buổi chiều?'),
(537, 4, 'learner', 'A morning appointment would be better.', 'Một lịch hẹn buổi sáng sẽ phù hợp hơn.'),
(537, 5, 'partner', 'Do you have your insurance details with you?', 'Bạn có mang thông tin bảo hiểm không?'),
(537, 6, 'learner', 'Yes. Which documents should I bring?', 'Có. Tôi nên mang những giấy tờ nào?'),
(537, 7, 'partner', 'Please bring your identification and relevant records.', 'Vui lòng mang giấy tờ tùy thân và hồ sơ liên quan.'),
(537, 8, 'learner', 'Thank you. Could you confirm the appointment time?', 'Cảm ơn. Bạn xác nhận giờ hẹn giúp tôi nhé?'),
(538, 1, 'partner', 'Do you have a prescription?', 'Bạn có đơn thuốc không?'),
(538, 2, 'learner', 'Yes. Could you help me read these instructions?', 'Có. Bạn giúp tôi đọc hướng dẫn này nhé?'),
(538, 3, 'partner', 'Which part would you like me to explain?', 'Bạn muốn tôi giải thích phần nào?'),
(538, 4, 'learner', 'I am not sure what this label means.', 'Tôi chưa hiểu nhãn này có nghĩa gì.'),
(538, 5, 'partner', 'I can explain the label and check with the pharmacist.', 'Tôi có thể giải thích nhãn và kiểm tra với dược sĩ.'),
(538, 6, 'learner', 'Please also tell me who to contact with questions.', 'Vui lòng cho tôi biết nên liên hệ ai nếu có thắc mắc.'),
(538, 7, 'partner', 'You can contact the pharmacy or your doctor.', 'Bạn có thể liên hệ nhà thuốc hoặc bác sĩ.'),
(538, 8, 'learner', 'Thank you. I will ask before changing anything.', 'Cảm ơn. Tôi sẽ hỏi trước khi thay đổi điều gì.'),
(539, 1, 'partner', 'Which course are you interested in?', 'Bạn quan tâm khóa học nào?'),
(539, 2, 'learner', 'I would like to learn about the evening classes.', 'Tôi muốn tìm hiểu các lớp buổi tối.'),
(539, 3, 'partner', 'What is your current level?', 'Trình độ hiện tại của bạn thế nào?'),
(539, 4, 'learner', 'I am a beginner and need a practical course.', 'Tôi mới bắt đầu và cần khóa học thực tế.'),
(539, 5, 'partner', 'Would you like information about the fees?', 'Bạn muốn biết thông tin học phí không?'),
(539, 6, 'learner', 'Yes. Could you explain the total cost?', 'Có. Bạn giải thích tổng chi phí giúp tôi nhé?'),
(539, 7, 'partner', 'I can send you the course details and application steps.', 'Tôi có thể gửi thông tin khóa học và các bước đăng ký.'),
(539, 8, 'learner', 'Thank you. What documents do I need to apply?', 'Cảm ơn. Tôi cần giấy tờ gì để đăng ký?'),
(540, 1, 'partner', 'Do you have a question about the assignment?', 'Bạn có câu hỏi về bài tập không?'),
(540, 2, 'learner', 'Could you explain what we need to submit?', 'Thầy/cô giải thích chúng em cần nộp gì nhé?'),
(540, 3, 'partner', 'You need to prepare a short group presentation.', 'Các em cần chuẩn bị một bài thuyết trình nhóm ngắn.'),
(540, 4, 'learner', 'How many students should be in each group?', 'Mỗi nhóm nên có bao nhiêu sinh viên?'),
(540, 5, 'partner', 'Please check the instructions for the group size.', 'Hãy xem hướng dẫn về số thành viên mỗi nhóm.'),
(540, 6, 'learner', 'Where can we find the marking criteria?', 'Chúng em tìm tiêu chí chấm điểm ở đâu?'),
(540, 7, 'partner', 'They are included in the assignment document.', 'Các tiêu chí nằm trong tài liệu bài tập.'),
(540, 8, 'learner', 'Thank you. We will review them before starting.', 'Cảm ơn. Chúng em sẽ xem lại trước khi bắt đầu.'),
(541, 1, 'partner', 'Could you tell me about yourself?', 'Bạn giới thiệu về bản thân được không?'),
(541, 2, 'learner', 'I have experience in customer service.', 'Tôi có kinh nghiệm trong dịch vụ khách hàng.'),
(541, 3, 'partner', 'What are your main strengths?', 'Điểm mạnh chính của bạn là gì?'),
(541, 4, 'learner', 'I communicate clearly and enjoy solving problems.', 'Tôi giao tiếp rõ ràng và thích giải quyết vấn đề.'),
(541, 5, 'partner', 'Why are you interested in this position?', 'Vì sao bạn quan tâm vị trí này?'),
(541, 6, 'learner', 'I would like to develop my skills in an international team.', 'Tôi muốn phát triển kỹ năng trong một đội ngũ quốc tế.'),
(541, 7, 'partner', 'Do you have any questions for us?', 'Bạn có câu hỏi nào cho chúng tôi không?'),
(541, 8, 'learner', 'Could you describe the daily responsibilities?', 'Bạn mô tả các trách nhiệm hằng ngày giúp tôi nhé?'),
(542, 1, 'partner', 'Would you like to review the job offer?', 'Bạn muốn xem lại đề nghị nhận việc không?'),
(542, 2, 'learner', 'Yes. Could you explain the working hours?', 'Có. Bạn giải thích giờ làm giúp tôi nhé?'),
(542, 3, 'partner', 'The schedule is described in the contract.', 'Lịch làm việc được mô tả trong hợp đồng.'),
(542, 4, 'learner', 'Are there any flexible working options?', 'Có hình thức làm việc linh hoạt nào không?'),
(542, 5, 'partner', 'We can discuss the options with the manager.', 'Chúng tôi có thể trao đổi các lựa chọn với quản lý.'),
(542, 6, 'learner', 'Could you also explain the benefits package?', 'Bạn giải thích thêm gói quyền lợi giúp tôi nhé?'),
(542, 7, 'partner', 'I will send you the written details.', 'Tôi sẽ gửi thông tin bằng văn bản.'),
(542, 8, 'learner', 'Thank you. I would like time to review them.', 'Cảm ơn. Tôi muốn có thời gian xem xét.'),
(543, 1, 'partner', 'How can I help you today?', 'Hôm nay tôi có thể giúp gì cho bạn?'),
(543, 2, 'learner', 'I would like to open a bank account.', 'Tôi muốn mở tài khoản ngân hàng.'),
(543, 3, 'partner', 'What type of account do you need?', 'Bạn cần loại tài khoản nào?'),
(543, 4, 'learner', 'I need an account for my everyday expenses.', 'Tôi cần tài khoản cho các khoản chi hằng ngày.'),
(543, 5, 'partner', 'Would you like information about the fees?', 'Bạn muốn biết thông tin về phí không?'),
(543, 6, 'learner', 'Yes. Are there any monthly charges?', 'Có. Có khoản phí hằng tháng nào không?'),
(543, 7, 'partner', 'I can explain the current terms and required documents.', 'Tôi có thể giải thích điều khoản hiện tại và giấy tờ cần có.'),
(543, 8, 'learner', 'Thank you. Can I manage the account online?', 'Cảm ơn. Tôi quản lý tài khoản trực tuyến được không?'),
(544, 1, 'partner', 'What seems to be the problem?', 'Bạn đang gặp vấn đề gì?'),
(544, 2, 'learner', 'I do not recognize this transaction.', 'Tôi không nhận ra giao dịch này.'),
(544, 3, 'partner', 'When did you notice it?', 'Bạn nhận thấy giao dịch đó khi nào?'),
(544, 4, 'learner', 'I saw it on my statement this morning.', 'Tôi thấy trên sao kê sáng nay.'),
(544, 5, 'partner', 'We can explain how to report the transaction securely.', 'Chúng tôi có thể giải thích cách báo giao dịch an toàn.'),
(544, 6, 'learner', 'Should I request that the card be blocked?', 'Tôi có nên yêu cầu khóa thẻ không?'),
(544, 7, 'partner', 'Please follow our secure verification process first.', 'Trước tiên hãy làm theo quy trình xác minh an toàn.'),
(544, 8, 'learner', 'Thank you. Please explain the next steps.', 'Cảm ơn. Vui lòng giải thích các bước tiếp theo.'),
(545, 1, 'partner', 'When will the shipment be ready?', 'Khi nào lô hàng sẽ sẵn sàng?'),
(545, 2, 'learner', 'The boxes will be ready tomorrow morning.', 'Các thùng hàng sẽ sẵn sàng vào sáng mai.'),
(545, 3, 'partner', 'Could you confirm the pickup address?', 'Bạn xác nhận địa chỉ lấy hàng nhé?'),
(545, 4, 'learner', 'I will send the warehouse address by email.', 'Tôi sẽ gửi địa chỉ kho qua email.'),
(545, 5, 'partner', 'Do you have the invoice and packing list?', 'Bạn có hóa đơn và danh sách đóng gói không?'),
(545, 6, 'learner', 'Yes. Please let me know if anything else is required.', 'Có. Vui lòng báo nếu cần thêm giấy tờ.'),
(545, 7, 'partner', 'We will review the documents before confirming collection.', 'Chúng tôi sẽ kiểm tra giấy tờ trước khi xác nhận lấy hàng.'),
(545, 8, 'learner', 'Thank you. Could you confirm the pickup window?', 'Cảm ơn. Bạn xác nhận khung giờ lấy hàng giúp tôi nhé?'),
(546, 1, 'partner', 'Could I have your tracking number?', 'Bạn cho tôi mã theo dõi đơn nhé?'),
(546, 2, 'learner', 'Here it is. The delivery seems to be delayed.', 'Mã đây. Việc giao hàng có vẻ bị chậm.'),
(546, 3, 'partner', 'Let me check the latest update.', 'Để tôi kiểm tra cập nhật mới nhất.'),
(546, 4, 'learner', 'Is the shipment waiting for customs clearance?', 'Lô hàng có đang chờ thông quan không?'),
(546, 5, 'partner', 'We need to confirm that with the relevant team.', 'Chúng tôi cần xác nhận với bộ phận liên quan.'),
(546, 6, 'learner', 'Do you need any documents from me?', 'Bạn cần giấy tờ nào từ tôi không?'),
(546, 7, 'partner', 'I will let you know after checking.', 'Tôi sẽ báo sau khi kiểm tra.'),
(546, 8, 'learner', 'Thank you. Please keep me informed.', 'Cảm ơn. Vui lòng cập nhật cho tôi.'),
(547, 1, 'partner', 'Good morning. How can I help?', 'Chào buổi sáng. Tôi có thể giúp gì?'),
(547, 2, 'learner', 'Could you recommend something to do nearby?', 'Bạn gợi ý hoạt động gần đây được không?'),
(547, 3, 'partner', 'Would you prefer a tour or a quiet activity?', 'Bạn thích đi tour hay hoạt động nhẹ nhàng?'),
(547, 4, 'learner', 'A local walking tour would be nice.', 'Một tour đi bộ địa phương sẽ phù hợp.'),
(547, 5, 'partner', 'I can check the available options.', 'Tôi có thể kiểm tra các lựa chọn còn trống.'),
(547, 6, 'learner', 'Could you tell me the price before booking?', 'Bạn cho tôi biết giá trước khi đặt nhé?'),
(547, 7, 'partner', 'Of course. I will confirm the details first.', 'Được chứ. Tôi sẽ xác nhận thông tin trước.'),
(547, 8, 'learner', 'Thank you. Please include the meeting point.', 'Cảm ơn. Vui lòng cho biết cả điểm tập trung.'),
(548, 1, 'partner', 'What kind of event are you planning?', 'Bạn dự định tổ chức sự kiện nào?'),
(548, 2, 'learner', 'We are planning a small business meeting.', 'Chúng tôi dự định tổ chức cuộc họp doanh nghiệp nhỏ.'),
(548, 3, 'partner', 'How many people do you expect?', 'Bạn dự kiến có bao nhiêu người?'),
(548, 4, 'learner', 'We expect around twenty participants.', 'Chúng tôi dự kiến khoảng hai mươi người.'),
(548, 5, 'partner', 'Do you need any presentation equipment?', 'Bạn cần thiết bị thuyết trình không?'),
(548, 6, 'learner', 'We need a projector and reliable internet access.', 'Chúng tôi cần máy chiếu và kết nối internet ổn định.'),
(548, 7, 'partner', 'I can prepare a quotation based on your requirements.', 'Tôi có thể chuẩn bị báo giá theo yêu cầu của bạn.'),
(548, 8, 'learner', 'Thank you. Please include any additional fees.', 'Cảm ơn. Vui lòng tính cả các khoản phí bổ sung.'),
(549, 1, 'partner', 'What is the main goal of this campaign?', 'Mục tiêu chính của chiến dịch này là gì?'),
(549, 2, 'learner', 'We want more people to know about our new service.', 'Chúng tôi muốn nhiều người biết đến dịch vụ mới.'),
(549, 3, 'partner', 'Who is your target audience?', 'Đối tượng khách hàng mục tiêu của bạn là ai?'),
(549, 4, 'learner', 'We are focusing on working adults.', 'Chúng tôi tập trung vào người trưởng thành đi làm.'),
(549, 5, 'partner', 'Do you have a budget for the campaign?', 'Bạn có ngân sách cho chiến dịch không?'),
(549, 6, 'learner', 'Could you suggest options at different price levels?', 'Bạn gợi ý các lựa chọn ở nhiều mức giá nhé?'),
(549, 7, 'partner', 'Yes. I will prepare a proposal for you.', 'Được. Tôi sẽ chuẩn bị đề xuất cho bạn.'),
(549, 8, 'learner', 'Thank you. Please explain how we will measure success.', 'Cảm ơn. Vui lòng giải thích cách đo lường thành công.'),
(550, 1, 'partner', 'Would you like an overview of the results?', 'Bạn muốn xem tổng quan kết quả không?'),
(550, 2, 'learner', 'Yes. Which numbers should we focus on?', 'Có. Chúng ta nên tập trung vào số liệu nào?'),
(550, 3, 'partner', 'We can compare reach, engagement and enquiries.', 'Chúng ta có thể so sánh độ tiếp cận, tương tác và lượt hỏi thông tin.'),
(550, 4, 'learner', 'Could you explain what those figures mean?', 'Bạn giải thích ý nghĩa các số liệu đó nhé?'),
(550, 5, 'partner', 'I will explain each measure and its limitations.', 'Tôi sẽ giải thích từng chỉ số và giới hạn của nó.'),
(550, 6, 'learner', 'What could we improve in the next campaign?', 'Chúng ta có thể cải thiện gì ở chiến dịch tiếp theo?'),
(550, 7, 'partner', 'Let us review the feedback before making changes.', 'Hãy xem phản hồi trước khi thay đổi.'),
(550, 8, 'learner', 'That sounds good. Please send me the report.', 'Hợp lý đấy. Vui lòng gửi báo cáo cho tôi.');
